    </div>
  </div>
);

/**
 * 从 File 创建并使用 object URL 的视频缩略图，避免每次渲染都创建新 URL
 */
const VideoThumbnailFromBlob: React.FC<{
  file: File;
  className: string;
  style: React.CSSProperties;
}> = ({ file, className, style }) => {
  const [objectUrl, setObjectUrl] = useState<string | null>(() => null);

  useEffect(() => {
    const url = URL.createObjectURL(file);
    setObjectUrl(url);
    return () => {
      URL.revokeObjectURL(url);
    };
  }, [file]);

  if (!objectUrl) return null;

  return <VideoThumbnail src={objectUrl} className={className} style={style} />;
};

/**
 * AttachmentFileIcon 组件 - 附件文件图标组件
 *
 * 该组件根据文件类型显示不同的图标或预览。如果是图片文件，则显示图片预览；
 * 如果是其他类型文件，则显示对应的文件图标。
 *
 * @component
 * @description 附件文件图标组件，根据文件类型显示图标或预览
 * @param {Object} props - 组件属性
 * @param {AttachmentFile} props.file - 附件文件对象
 * @param {string} [props.className] - 自定义CSS类名
 * @param {React.CSSProperties} [props.style] - 自定义样式
 *
 * @example
 * ```tsx
 * <AttachmentFileIcon
 *   file={fileData}
 *   className="custom-icon"
 *   style={{ fontSize: '24px' }}
 * />
 * ```
 *
 * @returns {React.ReactElement} 渲染的文件图标或预览组件
 *
 * @remarks
 * - 支持图片文件预览显示
 * - 支持多种文件类型图标
 * - 自动识别文件类型
 * - 提供自定义样式支持
 * - 响应式布局
 * - 图片自适应显示
 * - 图标居中显示
 */
const IMAGE_STYLE: React.CSSProperties = {
  width: '40px',
  height: '40px',
  overflow: 'hidden',
};

/** 无 url/previewUrl 时展示文件大小与格式的占位块（内容未拿到） */
export const FileMetaPlaceholder: React.FC<{
  file: AttachmentFile;
  className?: string;
  style?: React.CSSProperties;
}> = ({ file, className, style }) => {
  const sizeBytes = file.size ?? file.uploadResponse?.fileSize ?? 0;
  const sizeText = sizeBytes > 0 ? kbToSize(sizeBytes / 1024) : '';
  const extFromName = file.name ? file.name.split('.').pop() || '' : '';
  const rawFormat = file.uploadResponse?.fileType ?? file.type ?? extFromName;
  const formatSuffix = rawFormat.includes('/')
    ? (rawFormat.split('/').pop() ?? '').toUpperCase()
    : rawFormat.toUpperCase();
  const formatText = formatSuffix || '-';
  return (
    <Tooltip title={file.name}>
      <div
        className={className}
        style={{
          height: 48,
          boxSizing: 'border-box',
          display: 'flex',
          justifyContent: 'center',
          borderRadius: 'var(--radius-base, 4px)',
          background: 'var(--color-fill-quaternary, rgba(0,0,0,0.04))',
          fontSize: 10,
          color: 'var(--color-text-tertiary, rgba(0,0,0,0.45))',
          lineHeight: 1.2,
          overflow: 'hidden',
          flex: 1,
          minWidth: 80,
          padding: 'var(--padding-1x) var(--padding-2x)',
          flexDirection: 'column',
          ...style,
        }}
      >
        {formatText && (
          <span
            style={{
              lineClamp: 1,
              lineHeight: '20px',
              height: '20px',
              boxSizing: 'border-box',
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              minWidth: 0,
              maxWidth: '100%',
            }}
          >
            {formatText}
          </span>
        )}
        {sizeText && (
          <span
            style={{
              lineClamp: 1,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              minWidth: 0,
              boxSizing: 'border-box',
              lineHeight: '20px',
              height: '20px',
              maxWidth: '100%',
            }}
          >
            {sizeText}
          </span>
        )}
      </div>
    </Tooltip>
  );
};

const IMAGE_PREVIEW_CONFIG = {
  mask: (
    <div>
      <Eye />
    </div>
  ),
  visible: false,
};

export const AttachmentFileIcon: React.FC<{
  file: AttachmentFile;
  className: string;
  style?: React.CSSProperties;
}> = (props) => {
  const { file, className } = props;

  // 上传中状态（兼容 pending）
  if (file.status === 'uploading' || file.status === 'pending') {
    return <FileUploadingSpin />;
  }

  // 错误状态
  if (file.status === 'error') {
    return <FileFailed />;
  }

  // 图片文件预览
  if (isImageFile(file)) {
    return (
      <Image
        src={file.url}
        style={IMAGE_STYLE}
        rootClassName={className}
        preview={IMAGE_PREVIEW_CONFIG}
        alt={file.name}
      />
    );
  }

  // 视频文件缩略图预览（与图片类似，带播放按钮）
  if (isVideoFile(file)) {
    const videoUrl = file.previewUrl || file.url;
    if (videoUrl) {
      return (
        <VideoThumbnail
          src={videoUrl}
          className={className}
          style={IMAGE_STYLE}
        />
      );
    }
    if (file.size) {
      return (
        <VideoThumbnailFromBlob
          key={`${file.name}-${file.size}-${file.lastModified || 0}`}
          file={file}
          className={className}
          style={IMAGE_STYLE}
        />
      );
    }
  }

  // 其他类型文件图标
  const fileType = file.type?.split('/').at(-1) as FileType;
  return getFileTypeIcon(fileType, '', file.name);
};

/**
 * 上传响应对象类型
 */
export type UploadResponse = {
  contentId?: string | null;
  errorMessage?: string | null;
  fileId: string;
  fileName: string;
  fileSize?: number | null;
  fileType: string;
  fileUrl: string;
  uploadStatus: 'SUCCESS' | 'FAIL' | string;
};

export type AttachmentFile = File & {
  url?: string;
  status?: 'error' | 'uploading' | 'pending' | 'done';
  uuid?: string;
  size?: number | null;
  previewUrl?: string;
  /** 错误信息（如文件超限、上传失败等），在 status 为 error 时展示 */
  errorMessage?: string | null;
  /** 错误类型，如 FILE_SIZE_EXCEEDED 表示因大小超限不可重试 */
  errorCode?: string | null;
  /** 上传响应数据（使用 uploadWithResponse 时会填充此字段） */
  uploadResponse?: UploadResponse;
};

/**
 * 将KB转换为可读的文件大小格式
 * 支持从字节（B）到TB的所有单位，最小单位为B
 *
 * @param {number} kb - 文件大小（KB）
 * @returns {string} 格式化后的文件大小字符串
 *
 * @example
 * kbToSize(1073741824) // "1 TB"
 * kbToSize(1048576) // "1 GB"
 * kbToSize(1024) // "1 MB"
 * kbToSize(512) // "512 KB"
 * kbToSize(1) // "1 KB"
 * kbToSize(0.5) // "512 B"
 * kbToSize(0.1) // "102.4 B"
 * kbToSize(0.0001) // "0.1 B"
 * kbToSize(0) // "0 B"
 */
export const kbToSize = (kb: number) => {
  const sizes = ['B', 'KB', 'MB', 'GB', 'TB'];
  const bytes = kb * 1024;

  // 处理边界情况：0或负数直接返回0 B
  if (bytes <= 0) {
    return '0 B';
  }

  // 如果小于1KB，直接返回字节
  if (bytes < 1024) {
    return parseFloat(bytes.toFixed(2)) + ' ' + sizes[0];
  }

  const i = Math.floor(Math.log(bytes) / Math.log(1024));
  return parseFloat((bytes / Math.pow(1024, i)).toFixed(2)) + ' ' + sizes[i];
};

/**
 * 检查文件是否为图片类型
 * 通过 MIME 类型和文件扩展名双重判断
 *
 * @param {File} file - 要检查的文件
 * @returns {boolean} 是否为图片文件
 */
export const isImageFile = (file: File): boolean => {
  // 首先检查 MIME 类型
  if (file?.type?.startsWith('image/')) {
    return true;
  }

  // 如果 MIME 类型不可用或不准确，检查文件扩展名
  const imageExtensions = [
    '.jpg',
    '.jpeg',
    '.png',
    '.gif',
    '.bmp',
    '.webp',
    '.svg',
    '.ico',
    '.tiff',
    '.tif',
  ];

  const fileName = file.name.toLowerCase();
  return imageExtensions.some((ext) => fileName.endsWith(ext));
};

const VIDEO_EXTENSIONS = [
  '.mp4',
  '.webm',
  '.ogg',
  '.ogv',
  '.mov',
  '.avi',
  '.wmv',
  '.flv',
  '.m4v',
  '.mkv',
];

const hasVideoExtension = (pathOrName: string): boolean => {
  const lower = pathOrName?.toLowerCase() || '';
  const beforeQuery = lower.split('?')[0];
  return VIDEO_EXTENSIONS.some((ext) => beforeQuery.endsWith(ext));
};

/**
 * 检查文件是否为视频类型
 * 通过 MIME 类型和文件扩展名双重判断
 *
 * @param {File} file - 要检查的文件（含 AttachmentFile）
 * @returns {boolean} 是否为视频文件
 */
export const isVideoFile = (file: File): boolean => {
  if (file.type?.startsWith('video/')) {
    return true;
  }

  if (hasVideoExtension(file.name)) {
    return true;
  }

  const attachmentFile = file as File & { url?: string; previewUrl?: string };
  const url = attachmentFile.previewUrl || attachmentFile.url;
  return !!url && hasVideoExtension(url);
};

/**
 * 检查文件是否为可展示的媒体类型（图片或视频）
 */
export const isMediaFile = (file: File): boolean =>
  isImageFile(file) || isVideoFile(file);

/**
 * 是否为「仅元信息占位」状态：有 status 但无 url/previewUrl，内容未拿到时整行以 FileMetaPlaceholder 风格展示
 */
export const isAttachmentFileLoading = (status?: string | null): boolean =>
  status === 'uploading' || status === 'pending';

/**
 * 是否应该展示 FileMetaPlaceholder：
 * - 有状态
 * - 非 loading（uploading/pending）
 * - 且没有可预览 URL
 */
export const isFileMetaPlaceholderState = (
  file: File & { status?: string; url?: string; previewUrl?: string },
): boolean =>
  file.status !== undefined &&
  file.status !== null &&
  !isAttachmentFileLoading(file.status) &&
  !file.url &&
  !(file as { previewUrl?: string }).previewUrl;

